query:
mutation ExportData($format: ExportFormat!, $options: ExportOptions!) {
  exportData(format: $format, options: $options) {
    success
    exportId
    format
    downloadUrl
    fileSize
    recordCount
    progress {
      percentage
      stage
      estimatedCompletion
    }
    metadata {
      exportedAt
      schema {
        tables
        relations
        attributes
      }
      statistics {
        nodeCount
        relationCount
        tableCount
      }
    }
    errors {
      message
      severity
      affectedRecords
    }
  }
}
